<?php
require __DIR__.'/includes/db.php';
$slug=trim((string)($_GET['slug']??''));$story=null;$tracks=[];
if($slug!==''){$q=$pdo->prepare("SELECT * FROM stories WHERE slug=? AND status='published' AND story_type IN ('audio','both') LIMIT 1");$q->execute([$slug]);$story=$q->fetch();if($story){$q=$pdo->prepare("SELECT a.*,c.chapter_number,c.title AS chapter_title FROM audio_tracks a LEFT JOIN chapters c ON c.id=a.chapter_id WHERE a.story_id=? AND a.status='published' ORDER BY a.track_order,a.id");$q->execute([$story['id']]);$tracks=$q->fetchAll();}}
if(!$story)http_response_code(404);
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b0910"><title><?= $story?e($story['title']).' – Nghe truyện audio | Truyện Đêm':'Không tìm thấy truyện audio'?></title><link rel="stylesheet" href="/css/style.css"><link rel="stylesheet" href="/css/site-matte-black.css"><link rel="stylesheet" href="/css/audio-post.css?v=20261120-2"></head><body class="story-site audio-post-page"><?php require __DIR__.'/includes/header.php';?>
<main class="listen-page">
<?php if(!$story):?><section class="listen-empty"><span>☾ TRUYỆN ĐÊM</span><h1>Không tìm thấy truyện audio</h1><p>Truyện có thể đã bị ẩn hoặc đường dẫn không còn tồn tại.</p><a href="/library.php">Quay lại thư viện</a></section>
<?php else:?>
<a class="listen-back" href="/library.php">← Thư viện truyện</a>
<section class="listen-hero"><div class="listen-cover-wrap"><?php if(!empty($story['cover_url'])):?><img class="listen-cover" src="<?=e($story['cover_url'])?>" alt="<?=e($story['title'])?>"><?php else:?><div class="listen-cover listen-cover-placeholder">☾<small>TRUYỆN ĐÊM</small></div><?php endif;?><span class="listen-cover-glow"></span></div><div class="listen-intro"><span class="listen-eyebrow"><i></i> AUDIO ORIGINAL</span><h1><?=e($story['title'])?></h1><p class="listen-description"><?=e($story['description']??'')?></p><div class="listen-byline"><span>✍ <?=e($story['author']?:'Truyện Đêm')?></span><?php if(!empty($story['category'])):?><span>• <?=e($story['category'])?></span><?php endif;?></div><div class="listen-stats"><span>♫ <?=count($tracks)?> track</span><span>Đeo tai nghe để có trải nghiệm tốt hơn</span></div></div></section>
<section class="listen-player-panel"><div class="listen-player-heading"><div><span class="listen-eyebrow">NOW PLAYING</span><h2 id="listen-now-title"><?= $tracks?e($tracks[0]['title']):'Chưa có tập audio'?></h2><p id="listen-now-sub"><?= $tracks?($tracks[0]['chapter_id']?'Chương '.(int)$tracks[0]['chapter_number'].' · '.e($tracks[0]['chapter_title']):'Tập audio'):'Audio đang được cập nhật'?></p></div><div class="listen-playing-mark" id="listen-playing-mark"><i></i><i></i><i></i><i></i></div></div>
<audio id="listen-audio" preload="metadata"></audio><div class="listen-progress-row"><span id="listen-current">0:00</span><input id="listen-progress" type="range" min="0" max="1000" value="0" aria-label="Tiến trình phát"><span id="listen-duration">0:00</span></div><div class="listen-controls"><button type="button" class="listen-small-control" id="listen-prev" aria-label="Tập trước" <?=!$tracks?'disabled':''?>>|◀</button><button type="button" class="listen-main-play" id="listen-play" aria-label="Phát" <?=!$tracks?'disabled':''?>>▶</button><button type="button" class="listen-small-control" id="listen-next" aria-label="Tập tiếp theo" <?=!$tracks?'disabled':''?>>▶|</button><label class="listen-volume">♪ <input id="listen-volume" type="range" min="0" max="1" step="0.05" value="0.85" aria-label="Âm lượng"></label></div><p class="listen-player-hint" id="listen-hint"><?= $tracks?'Chọn một tập bên dưới để bắt đầu nghe.':'Chưa có bản ghi âm được xuất bản.'?></p></section>
<section class="listen-queue"><div class="listen-queue-head"><div><span class="listen-eyebrow">YOUR LISTENING QUEUE</span><h2>Danh sách phát</h2></div><span class="listen-count"><?=count($tracks)?> tập</span></div>
<?php if(!$tracks):?><div class="listen-no-tracks">Các tập audio sẽ xuất hiện tại đây khi được đăng tải.</div><?php else:?><div class="listen-track-list"><?php foreach($tracks as $i=>$t):?><button type="button" class="listen-track<?=$i===0?' is-active':''?>" data-index="<?=$i?>" data-url="<?=e($t['audio_url'])?>" data-title="<?=e($t['title'])?>" data-sub="<?=e($t['chapter_id']?'Chương '.(int)$t['chapter_number'].' · '.$t['chapter_title']:'Tập audio')?>"><span class="listen-track-index"><span class="listen-track-number"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><span class="listen-track-eq"><i></i><i></i><i></i></span></span><span class="listen-track-copy"><strong><?=e($t['title'])?></strong><small><?=$t['chapter_id']?'Chương '.(int)$t['chapter_number'].' · '.e($t['chapter_title']):'Tập audio'?></small></span><span class="listen-track-play">▶</span></button><?php endforeach;?></div><?php endif;?></section>
<?php endif;?></main><?php require __DIR__.'/includes/footer.php';?>
<?php if($story&&$tracks):?><script>
(()=>{const a=document.getElementById('listen-audio'),rows=[...document.querySelectorAll('.listen-track')],play=document.getElementById('listen-play'),prev=document.getElementById('listen-prev'),next=document.getElementById('listen-next'),bar=document.getElementById('listen-progress'),cur=document.getElementById('listen-current'),dur=document.getElementById('listen-duration'),title=document.getElementById('listen-now-title'),sub=document.getElementById('listen-now-sub'),hint=document.getElementById('listen-hint'),mark=document.getElementById('listen-playing-mark');let idx=0;const time=n=>Number.isFinite(n)?Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0'):'0:00';function select(i,auto){idx=(i+rows.length)%rows.length;const r=rows[idx];a.src=r.dataset.url;title.textContent=r.dataset.title;sub.textContent=r.dataset.sub;rows.forEach((x,k)=>{x.classList.toggle('is-active',k===idx);x.classList.remove('is-playing')});bar.value=0;cur.textContent='0:00';dur.textContent='0:00';if(auto)a.play().catch(()=>hint.textContent='Không thể tự phát. Hãy nhấn nút phát để nghe.')}function state(){const on=!a.paused;play.textContent=on?'Ⅱ':'▶';mark.classList.toggle('is-playing',on);rows[idx]?.classList.toggle('is-playing',on);hint.textContent=on?'Đang phát · Chúc bạn nghe truyện vui vẻ.':'Đã tạm dừng'}rows.forEach((r,i)=>r.addEventListener('click',()=>select(i,true)));play.addEventListener('click',()=>{if(!a.src)select(idx,false);if(a.paused)a.play().catch(()=>hint.textContent='Không thể phát file audio này.');else a.pause()});prev.addEventListener('click',()=>select(idx-1,true));next.addEventListener('click',()=>select(idx+1,true));a.addEventListener('play',state);a.addEventListener('pause',state);a.addEventListener('timeupdate',()=>{cur.textContent=time(a.currentTime);if(Number.isFinite(a.duration)){bar.value=Math.round(a.currentTime/a.duration*1000);dur.textContent=time(a.duration)}});a.addEventListener('loadedmetadata',()=>dur.textContent=time(a.duration));a.addEventListener('ended',()=>{if(idx<rows.length-1)select(idx+1,true);else hint.textContent='Bạn đã nghe hết danh sách phát.'});a.addEventListener('error',()=>hint.textContent='Không tải được file audio. Vui lòng kiểm tra đường dẫn MP3.');bar.addEventListener('input',()=>{if(Number.isFinite(a.duration))a.currentTime=bar.value/1000*a.duration});document.getElementById('listen-volume').addEventListener('input',e=>a.volume=Number(e.target.value));a.volume=.85})();
</script><?php endif;?></body></html>